"use strict";(self.webpackChunktest_website=self.webpackChunktest_website||[]).push([[147627],{196011:(e,t,a)=>{a.r(t),a.d(t,{assets:()=>r,contentTitle:()=>s,default:()=>w,frontMatter:()=>h,metadata:()=>n,toc:()=>d});var n=a(319963),o=a(474848),i=a(28453);const h={tags:["UFO","2025-04"]},s="Philip Corso \u306e\u606f\u5b50\u306e\u8a3c\u8a00\uff1a\u6587\u5b57\u8d77\u3053\u3057",r={authorsImageUrls:[]},d=[{value:"\u524d\u7f6e\u304d",id:"\u524d\u7f6e\u304d",level:2},{value:"\u624b\u629c\u304d",id:"\u624b\u629c\u304d",level:2},{value:"Youtube \u52d5\u753b(2:47:12)",id:"youtube-\u52d5\u753b24712",level:2},{value:"FasterWhisper AI(large-v2 model)",id:"fasterwhisper-ailarge-v2-model",level:2}];function l(e){const t={h2:"h2",hr:"hr",p:"p",...(0,i.R)(),...e.components},{Details:a}=t;return a||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("Details",!0),(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.h2,{id:"\u524d\u7f6e\u304d",children:"\u524d\u7f6e\u304d"}),"\n",(0,o.jsx)(t.p,{children:"Philip Corso \u306e\u606f\u5b50\uff08Philip Corso, Jr.\uff09\u306e\u8a3c\u8a00\u52d5\u753b\u304c\u542b\u307e\u308c\u305f Greer \u304c\u516c\u958b\u3057\u305f\u52d5\u753b\u3002\u5192\u982d\u304b\u3089 27:56 \u307e\u3067\u304c\u8a72\u5f53\u3002\u4ee5\u964d\u306f\u5225\u4eba\u306e\u8a3c\u8a00\u3002"}),"\n",(0,o.jsx)(t.p,{children:"\u904e\u53bb\u8a18\u4e8b\u3001"}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)("a",{href:"http://news21c.blog.fc2.com/blog-entry-11832.html",children:"Philip Corso \u306e\u8a3c\u8a00\u304c\u634f\u9020\u3067\u3042\u308b\u3053\u3068\u3092\u793a\u3059\u3001\u5225\u306e\u6839\u62e0"}),"    (2018-06-16)"]}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)("a",{href:"http://news21c.blog.fc2.com/blog-entry-11888.html",children:"1957\u5e74\u3001Red Canyon\uff1aPhilip Corso \u304c\u6d1e\u7a9f\u3067 ET \u306b\u906d\u9047\u3057\u305f\u4e8b\u4ef6\u3000\uff08\u9014\u4e2d\uff1a\u305d\u306e3\uff09"}),"    (2018-06-24)"]}),"\n",(0,o.jsx)(t.p,{children:"\u3067\u53d6\u308a\u4e0a\u3052\u305f\u5185\u5bb9\u304c\u542b\u307e\u308c\u3066\u3044\u308b\u3002"}),"\n",(0,o.jsx)(t.p,{children:"\u4eca\u56de\u306f\u3001\u6587\u5b57\u8d77\u3053\u3057\u3092\u4ed8\u3051\u305f\u3002\u548c\u8a33\u306f\u7701\u7565\u3002\u5f8c\u65e5\u3001\u3053\u306e \u6587\u5b57\u8d77\u3053\u3057 \u3092\u5143\u306b\u3001AI \u306b\u3088\u308b\u8981\u70b9\u306e\u7b87\u6761\u66f8\u304d\u3092\u8ffd\u52a0\u3059\u308b\u304b\u3082\u3002"}),"\n",(0,o.jsx)(t.h2,{id:"\u624b\u629c\u304d",children:"\u624b\u629c\u304d"}),"\n",(0,o.jsx)(t.p,{children:"12:11  Philadelphia experimnt \u306e\u6587\u66f8\u304c"}),"\n",(0,o.jsx)(t.p,{children:"alien \u89e3\u5256\u52d5\u753b\u306b\u3064\u3044\u3066"}),"\n",(0,o.jsx)(t.p,{children:"20:50 UFO \u306f\u751f\u304d\u3066\u3044\u3066\u2026"}),"\n",(0,o.jsx)(t.p,{children:"25:13 pic \u8cc7\u6599"}),"\n",(0,o.jsx)(t.h2,{id:"youtube-\u52d5\u753b24712",children:"Youtube \u52d5\u753b(2:47:12)"}),"\n",(0,o.jsx)(t.p,{children:"The Truth Behind Fiber Optics and Lasers\u2014They\u2019re Not From Earth  Dr. Steven Greer"}),"\n",(0,o.jsx)(t.h2,{id:"fasterwhisper-ailarge-v2-model",children:"FasterWhisper AI(large-v2 model)"}),"\n",(0,o.jsxs)(a,{children:[(0,o.jsx)("summary",{children:"\u25bc\u5c55\u958b"}),(0,o.jsx)(t.p,{children:"Command of the 552 Missile Battalion. He had several incidences in the desert. One of them is a cave that the GI showed him that was there, and it was always animals, had water in the cave, and it was a cool place to go out of the desert. And often many of the men would go up there and himself just for excursion and something to do.\r\n(0:00:31)"}),(0,o.jsx)(t.p,{children:"You've got to understand Red Canyon is very isolated. There's no stores or anything around. They built a church there which I think was highly interesting. Later on there's a story that involves that. But anyway, he went to this cave and when he was in the cave he tells the story of the first meeting with the alien in the cave.\r\n(0:00:59)"}),(0,o.jsx)(t.p,{children:"He said he was kind of laying back, sleeping, relaxing, dozing off, and all of a sudden he rolled over and pulled his gun. They always wore their gun whenever they were off their post up there. And he pulled the gun and he pointed it toward this form, he says. He didn't recognize what the form was. So he asks, he says, friend or foe? The form said, neither.\r\n(0:01:23)"}),(0,o.jsx)(t.p,{children:"But he was very, very upset because the message came mentally and he figures how in the heck is this thing and what is it and what is it doing?\r\nHe later sees it move a little bit and he sees that it has a type of helmet on with a type of stone in the center of its head on a band.\r\n(0:01:40)"}),(0,o.jsx)(t.p,{children:"He drew pictures of it or had an artist draw it. This creature asked him to shut down his radars for 15 minutes. He says that he figured in his head, how does this thing know that I'm the only person that could give that command to shut these radars down? He asked the creature, well why should I do it or what's in it for me? The creature answered, a new world if you can take it.\r\n(0:02:07)"}),(0,o.jsx)(t.p,{children:"At the time that had little to no meaning to him, only in later days did it have a meaning to it.\r\nHe went out of the cave, called Sergeant Rexack, told him to shut down the radars and he says that as he was leaving the cave, he sees the creature standing in the end of the cave and he does kind of a gesture with his hand, which wasn't a salute or wasn't a wave or anything, but he saluted it back.\r\n(0:02:42)"}),(0,o.jsx)(t.p,{children:"And that was basically the end of the encounter there. He's on his radars, they picked up a ship moving over 3,000 miles an hour through the atmosphere. It went down near Red Canyon. So he had a light airplane then and he got the pilot, he flew up, looked around and he saw a shiny object on the ground.\r\n(0:03:06)"}),(0,o.jsx)(t.p,{children:"He figured that he would investigate closer by himself, so he landed, did not take anybody with him, got one of the old staff cars, went out into the desert and he says he found the craft. And it was, he says it was perfectly smooth, it was oval-shaped, more like a cigar than a saucer, stuck into a side or lesting against a rock sideways.\r\n(0:03:30)"}),(0,o.jsx)(t.p,{children:"He said this thing would fade out completely and then fade back in. He thought he was hallucinating and he couldn't figure this out, what was going on. He was scared to death, he says, but he managed to take a tumble weave and throw under it when it was faded, when it was gone, just to see if he was hallucinating or if it was real. It came back again, he says that he touched it, it was cool to the touch on the side.\r\n(0:03:57)"}),(0,o.jsx)(t.p,{children:"He says when it disappeared again or went back out of phase again, the tumble weave was crushed, so he knew it was physical. He said there were footprints around the craft. I always felt like there was more there that he hadn't told, just my personal feeling, because you don't see footprints in the craft, I don't think, without having a second encounter, but that's my own personal view.\r\n(0:04:22)"}),(0,o.jsx)(t.p,{children:"He says the ship began to vibrate, he says he got scared, he jumped back in the staff car, threw it in reverse, it went flying backwards, and he says the motor stalled. He said he saw the thing rise up, turn, and go up into the air, and then it went into an envelope that it kind of imploded into. And he says later on he told Von Braun about it, he told Olbert about it, which were on his scientific teams later on.\r\n(0:05:00)"}),(0,o.jsx)(t.p,{children:"He knew them because he was in charge of Operation Paperclip for President Eisenhower. So, you know, this is a matter of credentials, telling a story like this.\r\n(0:05:07)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"My wife and I always said this story is bull, you know, are we to believe him? I must say this about my father, when you see his presence on film, and if you knew my father for only a few minutes, he never would change his story, he would never make the fish longer. When he told the story he would tell it in front of anybody, he didn't care who they were, credibility, credentials, or whatever. He would tell it the same as he would tell any other story about MIAs or so like that, or, you know, such.\r\n(0:05:44)"}),(0,o.jsx)(t.p,{children:"They would do research for the White House, they were part of Operation Paperclip, they would do research on, for instance, if you want to know one of them, my dad was a declassifying officer on his Project Horizon. See, President Kennedy really didn't do such a great thing when he said we're going to send a moon landing by whenever it was, 1967, or whenever he promised this or the end of 1969. That had actually all been proposed in Project Horizon. Obviously, I would say that the President probably knew about this because it was classified at the time. Later on when it was put into the book, my dad was the declassifying officer on that, so he knew it was to put on.\r\n(0:06:30)"}),(0,o.jsx)(t.p,{children:"I remember seeing that as a boy by accident. I picked it up on his desk one day and it was about an inch thick and it had all color photos in it. And I said, wow, look at this space stuff. And of course, I didn't know what it was, if it was a fiction book or what it was, but I do remember seeing it.\r\n(0:06:49)"}),(0,o.jsx)(t.p,{children:"He speaks of a man named Wilbur Smith, which was a great investigator of UFOs and phenomena and built a lot of machinery for magnetism and along the Tesla lines that was Canadian. He was disgraced. Dad says later on, Dad exchanged metals with him in the 60s. Of course, Dad has discussed this issue with many politicians. He discussed this issue with Strom Thurmond. He discussed this issue with the CIA director J. Edgar Hoover. He's FBI. I'm sorry.\r\n(0:07:23)"}),(0,o.jsx)(t.p,{children:"He discussed this also with CIA leaders. I don't know who they were, but he says really all branches of the services and the intelligence community. He briefed several of the chiefs of staff.\r\nThey did keep the information from several presidents. They figured that they just did not have the matrix to be briefed on this subject. One was Carter. He would never know, they said.\r\n(0:07:54)"}),(0,o.jsx)(t.p,{children:"There was actually a group of about 30. Now, don't pin this number to an exact number, but he says about 30 key generals and key military and key congressional people, such as he briefed John McCormick, Speaker of the House. I was actually under his patronage for a while. I worked on Capitol Hill as a Capitol policeman and as a page.\r\n(0:08:23)"}),(0,o.jsx)(t.p,{children:"He briefed these people. He briefed Senator Strom Thurmond. Another congressman that Dad was very close to was John Feehan from Ohio. He briefed him. Why did they brief these certain people? It was part of my dad's agenda and others at the time to keep knowledge secret and to let knowledge out in certain areas. This was more or less a community of friends.\r\n(0:08:58)"}),(0,o.jsx)(t.p,{children:"There were many generals involved in this and their pack was the last to die could tell and the last that did die, you're blinking red, the last that did die was of course General Trudeau. And then my father told everything after General Trudeau, but if you notice there was never a word said before 1992. My father was on the National Security Council. Now this is a part here that becomes Freeman raised a question and it became very controversial when it should not have been.\r\n(0:09:33)"}),(0,o.jsx)(t.p,{children:"My father was not on the council, but he was an advisor to the council for the president. In other words, there's many advisors that sit in on council meetings and they just sit back and take notes and then report back to the president.\r\n(0:09:43)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"As far as being listed as part of the council, no, he was not. And why a big deal? Let's not go there. It just wasn't necessary. But to answer your question, I'm going to tell this in my words.\r\nThese weren't exactly my dad's words. I tried to keep his words pure, but it went something like this. Eisenhower, he says, asked him where these creatures were from.\r\n(0:10:09)"}),(0,o.jsx)(t.p,{children:"I'm speaking of Roswell. Dad says, we don't know. He says, what do they want? He said, we don't know that either.\r\nSo Ike, he said, said, well, Corso, what's your opinion? What should we say about it?\r\nAnd dad says, the answer to Ike was, look, we're all military men. Let's just say nothing.\r\nBut it did penetrate our airspace, so we have to treat them as foe.\r\n(0:10:37)"}),(0,o.jsx)(t.p,{children:"And so the cover-up, or whatever you want to call it, began. My father says there was never a cover-up, never intended to be a cover-up. With all these agencies, and with the White House not wanting to say anything, it shortly got written into mandate to be a cover-up. And that's how my father says, for instance, the government doesn't need to cover itself up.\r\n(0:11:03)"}),(0,o.jsx)(t.p,{children:"It's so inefficient it'll do it itself. But as you can see, this is developing a pattern. It wasn't just chance that my father was put in research and development in 1960 under foreign technology.\r\nBecause this is now the second time in the government, or second time that since he was in the career, you might say, from Fort Raleigh to Eisenhower to General Trudeau, this was no accident.\r\n(0:11:33)"}),(0,o.jsx)(t.p,{children:"Because you can see that Eisenhower was also another very important president that had this information and knew of this information. My dad says he knew of the information. What type of technologies and how were they transferred? I go back to where dad first inherited the file. The file General Trudeau had brought up as soon as he took his job.\r\nHad it brought up from the basements of the Pentagon. This file had a lock on it just like in our website.\r\n(0:12:02)"}),(0,o.jsx)(t.p,{children:"We tried to duplicate it. That's a four drawer and it was a three drawer, he speaks of on the films. It had materials in it. It had classified files in it. It had files on the Philadelphia experiment. It had files on many other government issues besides Roswell. But it did have some artifacts in it.\r\n(0:12:22)"}),(0,o.jsx)(t.p,{children:"These artifacts, my father said, there was actually a file that briefed where the artifacts came from. And it was indeed Roswell, 1947, July 4th. And these artifacts were, he speaks of laying three of them on a triangle on his desk. And General Trudeau walking in and saying, oh what's that junk on your desk? And dad would say, well you know these could change the world.\r\n(0:12:47)"}),(0,o.jsx)(t.p,{children:"And General Trudeau would say, yes I know. And we just hope that people that come afterwards will know what to do with these. The first was a piece of metal. And this metal was kind of different because it couldn't be penetrated, folded, creased, or sealed. But when they sent it to one of the laboratories, I remember dad saying they put a certain frequency and current to it and it became transparent. And it passed energy through it and it could be cut and destroyed in.\r\n(0:13:11)"}),(0,o.jsx)(t.p,{children:"Another object that he had was the first integrated circuit. More than an integrated circuit though, it was a wafer. A multi-stacked wafer with a kind of a prom window in the middle of it, partially burned on one end. Now this is the interesting part. My father says, by him concentrating on that, he could make it glow.\r\n(0:13:35)"}),(0,o.jsx)(t.p,{children:"It would glow a blue light. He also had fiber optics laying there. They didn't know what these things were. They figured they were wires of some sort, but didn't know how they operate. The interesting thing that shows you that we have not achieved a point of where these fiber optics are, is my dad would also hold them in his hand and when he closed his hand around them, the ends would be glowing.\r\n(0:13:53)"}),(0,o.jsx)(t.p,{children:"So this means they contained their own energy. We haven't reached this state yet of understanding how materials can atomically align and become opaque and such from that. One of the things that General Trudeau did say to my father though was, after they analyzed a metal, was that an alignment of atoms, any time my dad had any hint of it, he would take the team of Olbert and all of the Germans and scientific team and go to this facility instantly, because General Trudeau said that would be bigger than Los Alamos. There were other items.\r\n(0:14:35)"}),(0,o.jsx)(t.p,{children:"He spoke of an item that was moved over to human body, that went to either John Hopkins or Walter Reed. He never saw it again. He said it also couldn't be opened such. He had the first laser in his hand. They didn't know what it was. And he tells the story on film that he thought it was a flashlight and the batteries were dead.\r\n(0:14:52)"}),(0,o.jsx)(t.p,{children:"So he had no idea what this thing was. But when they put it to Fort Belvoir and they put the energies and currents to it and this and that, the first laser appeared. But he says that the characteristic of this laser is nothing like we have today. It was molecule size. He was sorry he wrote the book.\r\n(0:15:11)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"He was sorry he exposed the family to the ridicule, to the lawsuits. It's been very tough on our entire family. He did not want to die, leaving us with these problems. We were very fortunate to find an angel, a true angel in Mr. Kent. If it wasn't for this man, I certainly would not be sitting in front of this camera now.\r\n(0:15:41)"}),(0,o.jsx)(t.p,{children:"Just hope that the future people such as yourself and me will know what to do with this type of knowledge that this man brought forward. I do say that he is the first man to come forward in a high capacity and possibly it will start to snowball going down the hill, getting larger and larger.\r\n(0:15:58)"}),(0,o.jsx)(t.p,{children:"I certainly hope so because I'm sure then he would be looking down and be proud of us. Of course, the Paramount company would be Bell Laboratories. As most of you know about the lawsuit between American Computer and Bell Laboratories and no previous history of inventing the integrated circuit. Now, let me set something straight for the record.\r\nI'm doing like my father did. I must be a product of him. The transistor is an earth invention.\r\n(0:16:24)"}),(0,o.jsx)(t.p,{children:"Okay, and people say, yes, it did come in 1948, began this research on it and this and that.\r\nHas nothing to do with the integrated circuit except for that it is solid state and it did begin the technology. And as they would plant some of this technology such as night vision, they would plant this technology into areas that were already existing, already working on these areas. For instance, there was an infrared night viewing device or such that came from German technology at Fort Belvoir. Well, that would be the natural place to take the lens from one of the alien's eyes.\r\n(0:17:06)"}),(0,o.jsx)(t.p,{children:"And dad says when they held it up in the hallway, they could see movements in the background of soldiers or people moving and such. Now, it again contained its own energy, nothing like we have today. So they planted these R&D projects in already existing... Now, they didn't implant the artifact. That's a big misconception too. They gave them a procurement, they gave them the funding, they gave them what to develop toward.\r\n(0:17:32)"}),(0,o.jsx)(t.p,{children:"And then they would insert from their own laboratories certain knowledges to keep them going on the right path, to keep them developing. And if it took the artifact to get the final product, they did this. And it wasn't being done benevolently. It was being done for the Army's own advantage over the other services and over our enemies and such like that.\r\n(0:18:01)"}),(0,o.jsx)(t.p,{children:"There was no reason that the public deserved it or the human beings or kindness or such like that. It was strictly a military operation. He says that the Air Force had this material from Roswell, the ships actually at Edwards Air Force Base, and that what they had was simply materials that were thrown into a jeep. The reason he knows that it was in the briefing file, in the file cabinet with the artifacts, Edwards Air Force Base. Now, Dad didn't tell that except for on his deathbed.\r\n(0:18:38)"}),(0,o.jsx)(t.p,{children:"I guess it's clear it was still classified. He was at nine levels above top secret. He was still, almost to his dying day, you could see him wavering between... sometimes he would say something and I would come back to him and he'd say, no, I never said that. For instance, he found a key. They couldn't get the ship opened up. So this is how I knew he was still in contact in later days, because they could not still analyze the ship.\r\n(0:19:06)"}),(0,o.jsx)(t.p,{children:"They had no way to open this ship. And he told me, after he had his first heart attack, that there was a key that they inserted and lines, seams came out everywhere. The extraterrestrial looked like, you know, the alien autopsy film. He was often asked if that was real. And he says, well, he can't testify whether it's real or not, but he says, let me tell you this, from an intelligence officer standpoint, there's three items that they, that whoever faked this film, if they did fake it, could not know. Number one, there was no emphatic system.\r\n(0:19:34)"}),(0,o.jsx)(t.p,{children:"Number two, it had two brains, four lobes. One of the brains was laced with ICs. Of course, that was not in the film, but it did have two films, the integrated circuit. The other part is, is that it had three eyelids. It had the outside one that was removable, had a membrane, and then the eyeball.\r\n(0:20:00)"}),(0,o.jsx)(t.p,{children:"So dad says, whoever faked this, if they did fake it, had the same report that he had from Walter Reed. By the way, the autopsies were done at Walter Reed. He said that the EB was indeed part of the craft, integrated into the craft, and it was the propulsion system.\r\n(0:20:13)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"A lack of a better word. There's really, there's really not a science to describe how the craft moved, but he said they knew it was integrated into the ship, and so were the other occupants of the ship, part of the guidance system, so on and so on. The ship was a living entity also.\r\nHe knew that from the reports.\r\n(0:20:46)"}),(0,o.jsx)(t.p,{children:"They knew it died. It simply turned from blue to brown, and died like a fish out of water, and so did the occupants shortly after.\r\nNow, I'll tell you something about also the EB. There was, he often spoke of a room in the Pentagon, which you had it like a jail door, and you slid it back, and you went in there, and you were not able to take any pencil, paper, recording device, or so, and you simply viewed documents, and then you came out with whatever you could store in your head.\r\n(0:21:15)"}),(0,o.jsx)(t.p,{children:"Once or twice, it led me to believe that there was something else that was kept in those room or rooms that would give information. He had a thread also that was from the clothing, and he says that the ship's skin, the alien's suit, silver suit, and his skin were all similar material. Absolutely, he was aware of other crashes.\r\n(0:21:47)"}),(0,o.jsx)(t.p,{children:"He says that the Germans told him that they had a crash, and that's where most of their technology, and their advanced materials, and their research as we brought them here. And this was part of a team that he worked with every day. He said there was another crash in 1957 in Corona. They knew that it was Stalin's number one mandate to steal Roswell technology.\r\n(0:22:21)"}),(0,o.jsx)(t.p,{children:"So they began an operation to hide it. They felt that the CIA was infiltrated. They felt that their funding would be cut off, and they felt that there would be nothing done with this material if they did indeed leave a paper trail or such like that.\r\nOur family was shocked. I mean, we absolutely were in disbelief that he could keep this a secret all these years. My mother would not be the type to even listen to anything like that.\r\n(0:22:53)"}),(0,o.jsx)(t.p,{children:"I'm sure that he didn't. I'm sure he never told another soul, except for people that were in the loop. He says that this group of 30 that were in charge of this technology, he says it wasn't a written mandate for them. They were simply hardened battlefield officers and they had an oath among themselves. So I guess men that you die next to and that you fight next to, that oath is probably just as good as if you signed it with the Lord. So I know my father never talked to anyone about this stuff.\r\n(0:23:34)"}),(0,o.jsx)(t.p,{children:"I'm positive. He told me many, many times there were no borders and have not been any borders. He say him and others that were in charge and political, they knew by 1983 we would become a user country. And that means we would consume about 90% of the world's goods and we were a fattened cow and would keep consuming it. This is the way the economic system is set up.\r\n(0:23:52)"}),(0,o.jsx)(t.p,{children:"He schooled me that he was taught by two popes the meaning of money. That was a deal he had worked out with them for doing certain favors for them, Father O'Flannery and two of the popes, Pope Pius I think the 12th and John the 5th or so, but don't quote those. I'd have to look in his records to see that. No, I was always a product of his schooling without me knowing about it.\r\n(0:24:18)"}),(0,o.jsx)(t.p,{children:"And now I see why. Maybe I have a job to do. He knew of this. Yes, he knew of MIAs, Korea. He knew quite a bit about Vietnam because of course him and Trudeau were going to go there.\r\n(0:24:34)"}),(0,o.jsx)(t.hr,{}),(0,o.jsx)(t.p,{children:"They were one of the candidates to take over the job. Yes, the world is entirely different than most people think it is. That came in later days when he told me that after the book.\r\nHe says the Vatican is indeed a very knowledgeable source. My dad knows of the MIAs that were left in Korea and why and how they were moved to Russia. And he testified on open and closed Senate committees on this.\r\n(0:25:08)"}),(0,o.jsx)(t.p,{children:"He says that the main reason that this was done is of course because of our liberal views or sympathizing with communist doctrine during the time. Blackmail. And it's in my father's writings in detail. And we did nothing. Did nothing. Right now there's no civilian machinery to handle another crash. If it happens again, it will simply go to the military and it will probably be the same situation that happened in Roswell. Even though the time is different, I don't think the military agenda is any different.\r\n(0:25:38)"}),(0,o.jsx)(t.p,{children:"It will come under national security and it will probably be the end of it. I think that we need a movement that we as people of the earth and people of the universe, that if a ship does crash here again, which my father said will happen, that we can be in charge of that or have salvage rights. My father after the book, he never knew John Glenn, but for some reason, I guess he thought he was very important.\r\n(0:26:14)"}),(0,o.jsx)(t.p,{children:"So he made a trip to Washington. There was another reason he made the trip to see Jean Dixon. She was very sick and he went in to see John Glenn and he gave John Glenn a document on an automobile, lightweight automobile. Now, whether it was a lightweight impractical or whatever, I don't know the entire, but John Glenn, he gave him debrief on it.\r\n(0:26:34)"}),(0,o.jsx)(t.p,{children:"It was about a quarter inch thick and it was from one of the laboratories that was funded. This is one of the items that came out of the Roswell crash that no one knows about until right now, except for the people that actually built and were in on the secret project. But someone might ask John Glenn if he remembers my dad's visitation.\r\n(0:26:59)"}),(0,o.jsx)(t.p,{children:"I think it was in 98. They would absolutely put the end to anyone that does that. That is something that has passed through many generations of our government. Not to be done.\r\nIn fact, even Teller was good friends with my father and they knew that also.\r\nHow they knew it, I don't know. But he did make that prediction and darn if it didn't happen.\r\n(0:27:22)"}),(0,o.jsx)(t.p,{children:"During the Reagan administration, I think when SDI was started, that it was a, this is, he told me later, you know, after 92 when he wrote the book, he says that that was a planetary defense system and that leaders of the world, most of the leaders knew that at the time. See the Cold War, talked about as a Cold War and he says the meaning was that it was an extraterrestrial war.\r\n(0:27:53)"}),(0,o.jsx)(t.p,{children:"He says they were terrorizing military facilities, terrorizing citizens and interfering with military facilities."})]}),"\n",(0,o.jsx)(t.p,{children:"(2025-04-24)"})]})}function w(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(l,{...e})}):l(e)}},28453:(e,t,a)=>{a.d(t,{R:()=>h,x:()=>s});var n=a(296540);const o={},i=n.createContext(o);function h(e){const t=n.useContext(i);return n.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:h(e.components),n.createElement(i.Provider,{value:t},e.children)}},319963:e=>{e.exports=JSON.parse('{"permalink":"/ds/en/blog/2025/04/24/corso_san","source":"@site/blog/2025-04-24-corso_san.md","title":"Philip Corso \u306e\u606f\u5b50\u306e\u8a3c\u8a00\uff1a\u6587\u5b57\u8d77\u3053\u3057","description":"\u524d\u7f6e\u304d","date":"2025-04-24T00:00:00.000Z","tags":[{"inline":false,"label":"UFO","permalink":"/ds/en/blog/tags/UFO","description":"UFO \u95a2\u9023"},{"inline":false,"label":"2025-04","permalink":"/ds/en/blog/tags/2025-04","description":"2025-04"}],"readingTime":23.81,"hasTruncateMarker":true,"authors":[],"frontMatter":{"tags":["UFO","2025-04"]},"unlisted":false,"nextItem":{"title":"\\"Philadelphia Experiment\\" \u306e\u771f\u5b9f\u3092\u660e\u304b\u3059\u2026\u3068\u3044\u3046\u52d5\u753b","permalink":"/ds/en/blog/2025/04/24/hoax_theory"}}')}}]);